/**
 * Unit tests for StringUtils.indexOfAny(String str, String[] searchStrs)
 * to maximize branch and line coverage.
 */
public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;









    @Test
    public void testIndexOfAny_MultipleMatches_ReturnsFirstOccurence() {
        // Covers: Logic where multiple strings match, must return the smallest index
        // "b" is at index 1, "a" is at index 0. Result should be 0.
        String[] searchStrs = {"b", "a", "c"};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }












}

